package org.apache.xml.utils.res;

//
//  LangResources_sv.properties
//

/**
 * The Swedish resource bundle.
 * @xsl.usage internal
 */
public class XResources_sv extends XResourceBundle
{

  /**
   * Get the association list.
   *
